// Browser-side lookup from scene id to its photo. The photos are generated by
// `npm run scenes` from the originals in src/assets/scene-backgrounds/.

const images = import.meta.glob("./assets/scenes/*.jpg", {
  eager: true,
  query: "?url",
  import: "default",
});

function url(name) {
  return images[`./assets/scenes/${name}.jpg`];
}

// Full-screen background for the TV.
export function sceneStyle(id) {
  return { background: `#111 url("${url(id)}") center / cover no-repeat` };
}

// Small button background, darkened a little so the white label stays readable.
export function sceneThumbStyle(id) {
  return {
    background: `linear-gradient(rgba(0,0,0,0.1), rgba(0,0,0,0.45)), #111 url("${url(
      `${id}-thumb`
    )}") center / cover no-repeat`,
  };
}
